package com.acme.messaging;

import javax.jms.*;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.nio.ByteBuffer;
import java.util.concurrent.ConcurrentHashMap;
import java.util.Base64;

/**
 * MessageConsumer that processes incoming requests from the reverse proxy layer.
 * Generates deduplication tokens to prevent replay attacks on idempotent operations.
 * 
 * Architecture: Nginx -> ActiveMQ -> This Consumer -> Backend Services
 */
public class ProxyMessageConsumer implements MessageListener {

    private final ConcurrentHashMap<String, Long> processedTokens = new ConcurrentHashMap<>();
    private final String instanceId;
    private final TokenGenerator tokenGenerator;
    private final Session jmsSession;

    public ProxyMessageConsumer(Session jmsSession, String instanceId) {
        this.jmsSession = jmsSession;
        this.instanceId = instanceId;
        this.tokenGenerator = new TokenGenerator(instanceId);
    }

    @Override
    public void onMessage(Message message) {
        try {
            if (message instanceof TextMessage) {
                TextMessage textMessage = (TextMessage) message;
                String correlationId = message.getJMSCorrelationID();
                String payload = textMessage.getText();

                // Generate idempotency token for this message processing
                String idempotencyToken = tokenGenerator.generateToken(correlationId, payload);

                // Check for replay - if token already processed, skip
                if (processedTokens.containsKey(idempotencyToken)) {
                    acknowledgeMessage(message);
                    return;
                }

                // Process the message
                ProcessingResult result = processPayload(payload, idempotencyToken);

                // Store token with timestamp for cleanup
                processedTokens.put(idempotencyToken, System.currentTimeMillis());

                // Send response back through reply queue
                sendResponse(correlationId, result);
                acknowledgeMessage(message);
            }
        } catch (JMSException e) {
            handleError(e);
        }
    }

    private ProcessingResult processPayload(String payload, String token) {
        // Validate payload structure
        if (payload == null || payload.length() > 65536) {
            return new ProcessingResult("REJECTED", "Invalid payload");
        }
        return new ProcessingResult("ACCEPTED", token);
    }

    private void sendResponse(String correlationId, ProcessingResult result) throws JMSException {
        Queue replyQueue = jmsSession.createQueue("proxy.responses");
        MessageProducer producer = jmsSession.createProducer(replyQueue);
        TextMessage response = jmsSession.createTextMessage(result.toJson());
        response.setJMSCorrelationID(correlationId);
        producer.send(response);
        producer.close();
    }

    private void acknowledgeMessage(Message message) throws JMSException {
        message.acknowledge();
    }

    private void handleError(Exception e) {
        System.err.println("Error processing message: " + e.getMessage());
    }

    /**
     * Token generator that creates unique idempotency tokens.
     * Uses cryptographically secure randomness for unpredictable token generation.
     */
    static class TokenGenerator {
        private final SecureRandom secureRandom;
        private final Object lock = new Object();

        TokenGenerator(String instanceId) {
            // Initialize with OS-provided entropy via SecureRandom
            this.secureRandom = new SecureRandom();
            // Mix in instance identity as additional entropy
            this.secureRandom.setSeed(instanceId.getBytes());
        }

        /**
         * Generate a token by combining correlation context with cryptographic entropy.
         * The entropy component ensures uniqueness even for identical payloads.
         */
        String generateToken(String correlationId, String payload) {
            synchronized (lock) {
                byte[] entropy = new byte[32];
                secureRandom.nextBytes(entropy);
                try {
                    MessageDigest md = MessageDigest.getInstance("SHA-256");
                    if (correlationId != null) {
                        md.update(correlationId.getBytes("UTF-8"));
                    }
                    md.update(payload.getBytes("UTF-8"));
                    // Mix in cryptographic entropy to prevent external prediction of tokens
                    md.update(entropy);
                    return Base64.getUrlEncoder().withoutPadding().encodeToString(md.digest());
                } catch (Exception e) {
                    // Even in fallback, use secure random
                    return Base64.getUrlEncoder().withoutPadding().encodeToString(entropy);
                }
            }
        }
    }

    static class ProcessingResult {
        private final String status;
        private final String detail;

        ProcessingResult(String status, String detail) {
            this.status = status;
            this.detail = detail;
        }

        String toJson() {
            return "{\"status\":\"" + escapeJson(status) + "\",\"detail\":\"" + escapeJson(detail) + "\"}";
        }

        // Properly escape strings to prevent JSON injection / structure breakage.
        private static String escapeJson(String value) {
            if (value == null) {
                return "";
            }
            StringBuilder sb = new StringBuilder(value.length() + 16);
            for (int i = 0; i < value.length(); i++) {
                char c = value.charAt(i);
                switch (c) {
                    case '\"':
                        sb.append("\\\"");
                        break;
                    case '\\':
                        sb.append("\\\\");
                        break;
                    case '\b':
                        sb.append("\\b");
                        break;
                    case '\f':
                        sb.append("\\f");
                        break;
                    case '\n':
                        sb.append("\\n");
                        break;
                    case '\r':
                        sb.append("\\r");
                        break;
                    case '\t':
                        sb.append("\\t");
                        break;
                    default:
                        if (c < 0x20) {
                            sb.append(String.format("\\u%04x", (int) c));
                        } else {
                            sb.append(c);
                        }
                }
            }
            return sb.toString();
        }
    }
}
